package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Real;
    in attribute io_2 : Boolean;
    attribute startupBlank : Boolean := true;
    perform action tick {
      first start;
      then if startupBlank and io_2 {
        first start;
        then assign startupBlank := false;
      }
    }
    out attribute io_0 : Boolean = (if not startupBlank and io_2 and io_1 < 10.0 ? true else false);
    out attribute io_3 : Integer = (if startupBlank or not io_2 ? 10000 else (if io_1 < 2.0 or io_1 > 400.0 ? 10000 else (if io_2 ? RealFunctions::floor(io_1) else 10000)));
  }
  part system : Controller;
}
